import csv
import io


def parse_csv(raw_csv: str):
    previous_limit = csv.field_size_limit()
    try:
        if len(raw_csv) > previous_limit:
            csv.field_size_limit(len(raw_csv))
        records = list(csv.reader(io.StringIO(raw_csv, newline=""), delimiter=",", quotechar='"'))
    finally:
        csv.field_size_limit(previous_limit)

    if not records:
        return {"columns": [], "rows": []}

    header_index = 0
    for index, row in enumerate(records):
        normalized = [cell.strip().lstrip("\ufeff").casefold() for cell in row]
        if (
            len(normalized) >= 3
            and normalized[0] == "district"
            and normalized[1] == "buffer extent description"
            and normalized[2] == "speed limit mph"
        ):
            header_index = index
            break

    header = records[header_index][:]
    rows = records[header_index + 1:]
    width = max([len(header)] + [len(row) for row in rows])
    header.extend([""] * (width - len(header)))

    reserved = {name for name in header if name}
    used = set()
    columns = []
    for index, name in enumerate(header):
        if not name:
            base = "column_{}".format(index + 1)
            name = base
            suffix = 2
            while name in reserved or name in used:
                name = "{}_{}".format(base, suffix)
                suffix += 1
        elif name in used:
            base = name
            suffix = 2
            while name in reserved or name in used:
                name = "{}_{}".format(base, suffix)
                suffix += 1
        columns.append(name)
        used.add(name)

    return {
        "columns": columns,
        "rows": [row + [""] * (width - len(row)) for row in rows],
    }
